// A 4 by 4 grid of lattice points with the diagonal y = x drawn dashed, one path
// that stays below it and one that crosses it.
size(400,400);
pen grid = gray(0.75) + 0.6;
pen diag = black + 1.2;
pen good = rgb(0.10,0.35,0.20) + 2;
pen bad = rgb(0.75,0.15,0.15) + 2;
real s = 70;
for (int i = 0; i <= 4; ++i) draw((i*s,0)--(i*s,4*s), grid);
for (int j = 0; j <= 4; ++j) draw((0,j*s)--(4*s,j*s), grid);
draw((0,0)--(4*s,4*s), diag);
draw((0,0)--(s,0)--(2*s,0)--(2*s,s)--(3*s,s)--(4*s,s), good);
draw((0,0)--(0,s)--(s,s)--(2*s,2*s)--(3*s,2*s)--(4*s,3*s), bad);
label("$y = x$", (4*s,4*s), NE);
label("stays below", (2*s,0), S);
label("crosses", (3*s,2*s), NW);

// A path tree on five labeled vertices, and the three deletions a Prufer code
// reads off it.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(480,420);
pen edge = black + 1.4;
pen gone = gray(0.55) + 2pt;
real s = 100;
// One row per step, top to bottom: the tree, then the tree with one more leaf
// deleted. A vertex already deleted stays on the row as a grey dot, so each row
// reads as the same tree one step further on rather than as a different picture.
for (int row = 0; row <= 3; ++row) {
  real y = 320 - row * 90;
  for (int i = 0; i <= 4; ++i) {
    if (i < row) {
      dot((i*s,y), gone);
      continue;
    }
    if (i < 4) draw((i*s,y)--((i+1)*s,y), edge);
    dot((i*s,y), black + 3pt);
    label("$" + string(i+1) + "$", (i*s,y), S);
  }
  if (row > 0) label("record $" + string(row+1) + "$", ((row-1)*s,y), N, red);
}
draw((2*s,320)--(2*s,-20), gray(0.7));
label("Prufer code: $2,3,4,5$", (2*s,-20), S);
